from _lib import *
lesson("impersonal-passive", "Strona bierna", "Bezosobowa strona bierna: it is said / he is thought to", 5,
 "Gdy przekazujemy opinie lub informacje bez podawania źródła, używamy czasowników raportujących (say, believe, think, report, expect, claim, know, consider, allege) w stronie biernej. Dwie konstrukcje: It + is said + that + zdanie, albo podmiot + is said + to + bezokolicznik (to do / to be doing / to have done).",
 "Typowe dla prasy, raportów i esejów – brzmi obiektywnie i formalnie. W Part 4 jedna z najczęstszych transformacji (People say that… → He is said to…).",
 dict(scheme="It + be + past participle + that…  |  Podmiot + be + past participle + to + bezokolicznik (prosty / ciągły / perfect)", word_order="It is believed that the thief escaped. → The thief is believed to have escaped.",
      affirmative=["It is said that he is very rich.", "He is said to be very rich.", "She is thought to have left the country."],
      negative=["He is not thought to be dangerous.", "It was not expected that the plan would fail."],
      questions=["Is he said to be the best candidate?", "Was it reported that anyone had been injured?"]),
 [X("It is said that the castle is haunted.", "Mówi się, że zamek jest nawiedzony.", "It + is said + that."),
  X("The castle is said to be haunted.", "Mówi się, że zamek jest nawiedzony.", "Podmiot + is said + to be."),
  X("The minister is believed to have resigned.", "Uważa się, że minister podał się do dymisji.", "Czynność wcześniejsza → to have + past participle."),
  X("The suspect is thought to be hiding in the forest.", "Przypuszcza się, że podejrzany ukrywa się w lesie.", "Czynność trwająca → to be + -ing."),
  X("It was reported that two people had been injured.", "Doniesiono, że dwie osoby zostały ranne.", "Czasy cofają się po was reported."),
  X("Two people were reported to have been injured.", "Doniesiono, że dwie osoby zostały ranne.", "To have been + past participle (bierna perfect)."),
  X("The company is expected to announce record profits.", "Oczekuje się, że firma ogłosi rekordowe zyski.", "Expected + to + bezokolicznik o przyszłości."),
  X("He is known to have a short temper.", "Wiadomo, że ma porywczy charakter.", "Known to have = wiadomo, że ma."),
  X("The painting is alleged to have been stolen.", "Rzekomo obraz został skradziony.", "Allege – w kontekście prawnym."),
  X("It is widely acknowledged that smoking causes cancer.", "Powszechnie uznaje się, że palenie powoduje raka.", "Przysłówek widely przed past participle."),
  X("There is said to be a tunnel under the city.", "Mówi się, że pod miastem jest tunel.", "There + is said + to be.")],
 [C("It is said that… vs He is said to…", "Znaczenie identyczne; druga forma jest krótsza i częstsza w Part 4.", "Gdy zdanie ma podmiot osobowy – zwykle forma z to."),
  C("to be vs to have been", "To be – równocześnie z mówieniem; to have been – wcześniej.", "He is said to have been ill (był chory wcześniej)."),
  C("is thought to be doing vs is thought to do", "Ciągła – coś dzieje się teraz; prosta – fakt/zwyczaj.", "Ukrywa się teraz → to be hiding.")],
 [W("He is said that he is rich.", "He is said to be rich. / It is said that he is rich.", "Nie łączymy dwóch konstrukcji."),
  W("She is believed to leave yesterday.", "She is believed to have left yesterday.", "Czynność przeszła → to have left."),
  W("It is thought him to be guilty.", "He is thought to be guilty.", "Osoba staje się podmiotem."),
  W("The prices are expected rising.", "Prices are expected to rise.", "Po expected – to + bezokolicznik.")],
 ["Czasownik suggest nie tworzy konstrukcji 'He is suggested to…' – używamy It is suggested that…",
  "Say w stronie biernej z osobą: He is said to (nie: He is told to – to inne znaczenie: kazano mu).",
  "Konstrukcja z there: There are thought to be 200 species."],
 [dict(en="The reforms are widely considered to have failed.", pl="Powszechnie uważa się, że reformy się nie powiodły.", note="Przysłówek + considered + to have."),
  dict(en="It has been suggested that the deadline be extended.", pl="Zasugerowano przedłużenie terminu.", note="Połączenie z subjunctive."),
  dict(en="Tourism is estimated to account for a tenth of the economy.", pl="Szacuje się, że turystyka odpowiada za jedną dziesiątą gospodarki.", note="Estimated + kolokacja account for.")],
 [G("The president is said ___ (be) in good health.", ["to be"], "Podmiot + is said + to be."),
  G("The robbers are thought ___ (escape) through the roof.", ["to have escaped"], "Wcześniejsza czynność → to have + past participle."),
  G("It ___ (believe) that the treasure is still buried here.", ["is believed"], "It + is + past participle."),
  M("The ship is reported ___ in a storm last night.", ["to have sunk", "to sink", "sinking", "that it sank"], "to have sunk", "Zdarzenie przeszłe.", {"to sink": "Prosty bezokolicznik – brak znaczenia przeszłości.", "sinking": "Po reported potrzebne jest to.", "that it sank": "Mieszanie dwóch konstrukcji."}),
  G("The suspect is believed ___ (stay) with friends at the moment.", ["to be staying"], "Teraz → to be + -ing."),
  K("People say that she is a brilliant pianist.", "SAID", "She ___ a brilliant pianist.", ["is said to be"], "is said to be."),
  K("People think the fire was started deliberately.", "THOUGHT", "The fire ___ started deliberately.", ["is thought to have been"], "Bierna perfect: to have been started."),
  E("He is known to be won three gold medals.", ["He is known to have won three gold medals.", "to have won"], "Przeszłe osiągnięcie → to have won.")],
 [K("Experts expect that prices will fall.", "EXPECTED", "Prices ___ fall.", ["are expected to"], "Prices are expected to fall."),
  K("It is believed that the band is recording a new album.", "BELIEVED", "The band ___ a new album.", ["is believed to be recording"], "Ciągła → to be recording."),
  K("They say there are wolves in these mountains.", "SAID", "There ___ wolves in these mountains.", ["are said to be"], "There are said to be."),
  G("It ___ (report) yesterday that the talks had collapsed.", ["was reported"], "Yesterday → was reported."),
  M("The author is considered ___ one of the best of her generation.", ["to be", "being", "that she is", "be"], "to be", "Considered + to be.", {"being": "Po considered w tej konstrukcji używamy to be.", "that she is": "Mieszanie konstrukcji.", "be": "Brakuje to."}),
  T("Uważa się, że on wyjechał za granicę.", ["He is believed to have gone abroad.", "He is thought to have gone abroad.", "It is believed that he has gone abroad.", "He is believed to have left the country.", "It is thought that he has gone abroad."], "is believed/thought + to have gone.")])
